values.value:
[
  [
    {
      "fieldName": "Label",
      "required": true,
      "customFieldParams": {
        "type": "text",
        "label": "Label"
      },
      "criteria": [
        {
          "isCreation": true
        }
      ]
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Prefix__c",
      "required": true,
      "toolTip": "Four digit letter used to denote the record type to use. The external system ID must start with this prefix.",
      "customFieldParams": {
        "type": "text",
        "label": "Prefix"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Record_Type_API_Name__c",
      "toolTip": "The record type label that corresponds to the prefix value.",
      "customFieldParams": {
        "type": "text",
        "label": "Record Type Label"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Skip_Giving_Summary_Calculation_v1__c",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Skip Giving Summary Calculation"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Hard_Soft_Credit_Calculation_Type__c",
      "customFieldParams": {
        "type": "picklist",
        "label": "Hard/Soft Credit Calculation Type",
        "customPicklistValuesString": [
          "Inherited",
          "Legacy",
          "Payment Amount",
          "Gift Amount / Non-Gift Amount / Payment Amount"
        ]
      }
    }
  ],
  [
    {
      "fieldName": "BLANK_ADDITIONAL_INFO",
      "customFieldParams": {
        "type": "header",
        "label": "Additional Information"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Require_Reviewed_Before_Posting__c",
      "toolTip": "When checked, the review transaction will always go to Manual Review until \"Reviewed\" is set as the status.",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Require Reviewed Before Posting"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Use_Design_on_Pledge_Gift_if_No_Design__c",
      "toolTip": "Override designations on review transaction with designations specified on the pledge/gift only if designations are not already specified.",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Use Design on Pledge/Gift if No Design"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Default_to_Manual_Review__c",
      "toolTip": "Whether or not to always set status to Manual Review instead of trying to automatically process it.",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Default to Manual Review"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Use_Designation_on_Pledge_Gift_Always__c",
      "toolTip": "Always override designations on review transaction with designations specified on the pledge/gift.",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Use Designation on Pledge/Gift Always"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Process_Separately_From_Load__c",
      "toolTip": "Inserts review transaction records first and then uses future methods to process the records.",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Process Separately From Load"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Clear_Remaining_Designation__c",
      "toolTip": "Clears the remaining designations on the review transactions that are not on the pledge/gift.",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Clear Remaining Designation"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Keep_Original_Comments__c",
      "toolTip": "Useful if we want to keep a history of the comments as the review transaction is being updated.",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Keep Original Comments"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Allow_Design_Mismatch_for_Pledge_Payment__c",
      "toolTip": "If the designation on the pledge payment does not match the designation on the pledge/gift, the pledge payment will apply to the one of the designation on the pledge/gift.",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Allow Design Mismatch for Pledge Payment"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Match_Against_Any_Pledge_Gift__c",
      "toolTip": "Uncheck if we only want to pay against the donor's pledges/gifts. Check means the donor can pay other people's pledges/gifts.",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Match Against Any Pledge/Gift"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Use_Appeal_on_Pledge_Gift_if_No_Appeal__c",
      "toolTip": "Override appeal on review transaction with appeal specified on the pledge/gift only if appeal is not already specified.",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Use Appeal on Pledge/Gift if No Appeal"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Match_Designation_If_No_Pledge_Gift__c",
      "toolTip": "This is only applicable if we are only allowing payment to the donor's pledges/gifts, not others. In this case, if we can't find the donor's pledge/gift specified by the review transaction, then we try to find one that matches the designations.",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Match Designation If No Pledge/Gift"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Use_Appeal_on_Gift_Pledge_Always__c",
      "toolTip": "Always override appeal on review transaction with appeal specified on the pledge/gift.",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Use Appeal on Pledge/Gift Always"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Matching_Order__c",
      "toolTip": "Overrides behavior involving the options listed, determining execution and order of priority.\nMatch Against Any Pledge/Gift\nMatch Against Donor Pledge/Gift (default behavior)\nMatch Designation If No Pledge/Gift\nCreate Gift If Pledge Not Found\n\nFormat: [\"Match Against Any Pledge/Gift\", \"Match Against Donor Pledge/Gift\", \"Create Gift If Pledge Not Found\"]",
      "jsonFieldParams": {
        "label": "Matching Order",
        "type": "list",
        "listType": "value",
        "valueCustomFieldParams": {
          "type": "picklist",
          "customPicklistValuesString": [
            "Match Against Any Pledge/Gift",
            "Match Against Donor Pledge/Gift",
            "Match Designation If No Pledge/Gift",
            "Create Gift If Pledge Not Found"
          ]
        }
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Only_Query_for_Active_Appeals__c",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Only Query for Active Appeals"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Only_Query_for_Active_Designations__c",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Only Query for Active Designations"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Do_Not_Use_Approval_Process__c",
      "toolTip": "Disable approval process. Session will still close and giving summary will still be calculated.",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Do Not Use Approval Process"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Pledge_Gift_Stage_Query_Override__c",
      "toolTip": "Overrides the stage condition that is used to query for pledges/gifts. Default is 'Active', 'Confirmed', 'Paid' and 'Funded'. Format is [\"Funded\",\"Active\"].",
      "jsonFieldParams": {
        "label": "Pledge/Gift Stage Query Override",
        "type": "list",
        "listType": "value",
        "valueCustomFieldParams": {
          "type": "picklist",
          "customPicklistValuesString": [
            "Active",
            "Confirmed",
            "Paid",
            "Funded"
          ]
        }
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Create_Gift_If_Pledge_Not_Found_v1__c",
      "toolTip": "Creates an outright gift instead of pledge payment if the pledge is not found. Should update Pledge/Gift Stage Query Override to use [\"Active\"] only.",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Create Gift If Pledge Not Found"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Use_Pledge_for_Payment_Amount_if_No_Amt__c",
      "toolTip": "Use the pledge to determine the payment amount only if the payment amount is not specified. This is based on the next installment for each designation that has not been fully paid yet, or the amount for each designation if recurring gift.",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Use Pledge for Payment Amount if No Amt"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Do_Not_Use_Hard_Credit__c",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Do Not Use Hard Credit"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Use_Pledge_for_Payment_Amount_Always__c",
      "toolTip": "Always use the pledge to determine the payment amount. This is based on the next installment for each designation that has not been fully paid yet, or the amount for each designation if recurring gift.",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Use Pledge for Payment Amount Always"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Do_Not_Use_Source_Contact_Soft_Credit__c",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Do Not Use Source Contact Soft Credit"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Create_Matching_Gift_From_Payments__c",
      "toolTip": "True, allows the creation of matching gifts from inserted payments. False, prevents the creation of matching gifts from inserted payments.",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Create Matching Gift From Payments"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Payment_Method__c",
      "customFieldParams": {
        "type": "picklist",
        "label": "Payment Method",
        "customPicklistValuesString": [
          "Inherited",
          "Legacy",
          "Gift Amount",
          "Gift Amount + Non-Gift Amount"
        ]
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Double_The_Donation_Account__c",
      "toolTip": "If multiple Double the Donation accounts are enabled, enter the DTD account API name associated with Double the Donation account to be used with this RTV2 prefix.",
      "customFieldParams": {
        "type": "text",
        "label": "Double The Donation Account"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Auto_Apply_Opp_Hard_Soft_Credits__c",
      "toolTip": "Transaction Types that will auto apply manual credits from the parent opportunity. Use any combination of \"Pledge Payment\" , \"Recurring Gift Payment\", \"Matching Gift Payment\", \"Auto Renewing Membership Payment\", \"Installment Based Membership Payment\", \"Auto Renewing POS Payment\", \"Installment Based POS Payment\", \"Partial Payment POS Payment\" delimited by \";\".",
      "jsonFieldParams": {
        "label": "Auto Apply Opp Hard/Soft Credits",
        "type": "listNotJSON",
        "listNotJSONSeperator": ";",
        "valueCustomFieldParams": {
          "type": "picklist",
          "customPicklistValuesString": [
            "Pledge Payment",
            "Recurring Gift Payment",
            "Matching Gift Payment",
            "Auto Renewing Membership Payment",
            "Installment Based Membership Payment",
            "Auto Renewing POS Payment",
            "Installment Based POS Payment",
            "Partial Payment POS Payment"
          ]
        }
      }
    }
  ],
  [
    {
      "fieldName": "BLANK_BIO_DEMO_INFO",
      "customFieldParams": {
        "type": "header",
        "label": "Bio Demo Information"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Match_Constituent_Against_Bio_Demo__c",
      "toolTip": "Matching the constituent using the bio information on the review transaction. Default is match against first name, last name and email. Cannot be used in conjunction with Match Organization Against Bio Demo.",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Match Constituent Against Bio Info"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Donor_External_ID_Override__c",
      "toolTip": "Specify another external ID to use to find constituents or organizations. Sample format is: [\"External_System_ID__c\",\"Donor_ID__c\",\"Payroll_ID__c\"]",
      "jsonFieldParams": {
        "label": "Donor External ID Override",
        "type": "list",
        "listType": "value",
        "valueCustomFieldParams": {
          "type": "text"
        }
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Match_Constituent_Override_Map__c",
      "toolTip": "Defines what fields to compare against between Review Transaction and Constituent to determine match. Format is {\"Constituent Field API Name\":\"Review Transaction Field API Name\"}. Must include at least {\"Email\":\"Email_1__c\"}.",
      "jsonFieldParams": {
        "label": "Match Constituent Override Map",
        "type": "object",
        "keyLabel": "Constituent Field",
        "valueLabel": "Review Transaction Field",
        "jsonKeysToValueList": [
          {
            "key": "[CUSTOM]",
            "valueCustomFieldParams": {
              "type": "text"
            }
          }
        ]
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Constituent_Fields_Query_Addition__c",
      "toolTip": "Additional fields to use when querying constituents. Used in conjunction with 'Create Constituent Map', 'Create Interim Map' and 'Match Constituent Map' when additional fields are needed for these. Format is [\"Field API Name 1\", \"Field API Name 2\"].",
      "jsonFieldParams": {
        "label": "Constituent Fields Query Addition",
        "type": "list",
        "listType": "value",
        "valueCustomFieldParams": {
          "type": "text"
        }
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Create_Constituent_If_Bio_Info_Not_Match__c",
      "toolTip": "Create constituent if bio information does not match. Needs to be used with 'Match Constituent Against Bio Info' checked.",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Create Constituent If Bio Info Not Match"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Use_Constit_on_Pledge_Gift_If_No_Donor__c",
      "toolTip": "Override constituent on review transaction with constituent specified on the pledge/gift only if the donor is not already specified.",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Use Constit on Pledge/Gift If No Donor"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Create_Constituent_Override_Map__c",
      "toolTip": "Defines what fields to use in Review Transaction to create corresponding fields in Constituent. Format is {“Constituent Field API Name”:“Review Transaction Field API Name”}.",
      "jsonFieldParams": {
        "label": "Create Constituent Override Map",
        "type": "object",
        "keyLabel": "Constituent Field",
        "valueLabel": "Review Transaction Field",
        "jsonKeysToValueList": [
          {
            "key": "[CUSTOM]",
            "valueCustomFieldParams": {
              "type": "text"
            }
          }
        ]
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Use_Constituent_on_Pledge_Gift_Always__c",
      "toolTip": "Always override constituent on review transaction with constituent specified on the pledge/gift.",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Use Constituent on Pledge/Gift Always"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Create_Interim_If_No_Constituent__c",
      "toolTip": "Create interim record if constituent is not found after no match from Match Constituent Against Bio Info and not created with Create Constituent If Bio Info Not Match.",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Create Con Interim If No Con or Org"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Create_Interim_Override_Map__c",
      "toolTip": "Defines what fields to use in Review Transaction to create corresponding fields in Interim. Format is {“Interim Field API Name”:”Review Transaction Field API Name”}. RecordTypeId supports specifying record type ID or API Name.",
      "jsonFieldParams": {
        "label": "Create Constituent Interim Override Map",
        "type": "object",
        "keyLabel": "Interim Field",
        "valueLabel": "Review Transaction Field",
        "jsonKeysToValueList": [
          {
            "key": "[CUSTOM]",
            "valueCustomFieldParams": {
              "type": "text"
            }
          }
        ]
      }
    },
    {
      "fieldName": "BLANK_INTERIM_OVERRDE_MAP",
      "customFieldParams": {
        "type": "blank"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Interim_Record_Type_Prefix__c",
      "toolTip": "Defines what record type to use in Review Transaction in conjunction with Create Interim If No Constituent setting.",
      "customFieldParams": {
        "type": "text",
        "label": "Constituent Interim Record Type Prefix"
      }
    },
    {
      "fieldName": "BLANK_Interim_Record_Type_Prefix",
      "customFieldParams": {
        "type": "blank"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Match_Organization_Against_Bio_Demo__c",
      "toolTip": "Matching the organization using the bio information on the review transaction. Default is match against organization name. Cannot be used in conjunction with Match Constituent Against Bio Info.",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Match Organization Against Bio Demo"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Organization_Fields_Query_Addition__c",
      "toolTip": "Additional fields to use when querying organizations. Format is [\"Field API Name 1\", \"Field API Name 2\"].",
      "jsonFieldParams": {
        "label": "Organization Fields Query Addition",
        "type": "list",
        "listType": "value",
        "valueCustomFieldParams": {
          "type": "text"
        }
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Match_Organization_Override_Map__c",
      "toolTip": "Defines what fields to compare against between Review Transaction and Organization to determine match. Format is {\"Organization Field API Name\":\"Review Transaction Field API Name\"}. Must include at least {\"Name\":\"Organization_Name__c\"}",
      "jsonFieldParams": {
        "label": "Match Organization Override Map",
        "type": "object",
        "keyLabel": "Organization Field",
        "valueLabel": "Review Transaction Field",
        "jsonKeysToValueList": [
          {
            "key": "[CUSTOM]",
            "valueCustomFieldParams": {
              "type": "text"
            }
          }
        ]
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Use_Org_on_Pledge_Gift_If_No_Donor__c",
      "toolTip": "Override organization on review transaction with organization specified on the pledge/gift only if the donor is not already specified.",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Use Org on Pledge/Gift If No Donor"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Create_Org_If_Bio_Info_Not_Match__c",
      "toolTip": "Create organization if bio information does not match. Needs to be used with 'Match Organization Against Bio Info' checked.",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Create Org If Bio Info Not Match"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Use_Organization_On_Pledge_Gift_Always__c",
      "toolTip": "Always override organization on review transaction with organization specified on the pledge/gift.",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Use Organization On Pledge/Gift Always"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Create_Organization_Override_Map__c",
      "toolTip": "Defines what fields to use in Review Transaction to create corresponding fields in Organization. Format is {“Organization Field API Name”:”Review Transaction Field API Name”}. RecordTypeId supports specifying record type ID or API Name.",
      "jsonFieldParams": {
        "label": "Create Organization Override Map",
        "type": "object",
        "keyLabel": "Organization Field",
        "valueLabel": "Review Transaction Field",
        "jsonKeysToValueList": [
          {
            "key": "[CUSTOM]",
            "valueCustomFieldParams": {
              "type": "text"
            }
          }
        ]
      }
    },
    {
      "fieldName": "BLANK_CREATE_ORG_OVERRIDE_MAP"
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Create_Interim_If_No_Organization__c",
      "toolTip": "Create interim record if organization is not found after no match from Match Organization Against Bio Info and not created with Create Org If Bio Info Not Match.",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Create Org Interim If No Con or Org"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Create_Organization_Interim_Override_Map__c",
      "toolTip": "Defines what fields to use in Review Transaction to create corresponding fields in Interim. Format is {“Interim Field API Name”:”Review Transaction Field API Name”}.",
      "jsonFieldParams": {
        "label": "Create Organization Interim Override Map",
        "type": "object",
        "keyLabel": "Interim Field",
        "valueLabel": "Review Transaction Field",
        "jsonKeysToValueList": [
          {
            "key": "[CUSTOM]",
            "valueCustomFieldParams": {
              "type": "text"
            }
          }
        ]
      }
    },
    {
      "fieldName": "BLANK_CREATE_ORG_INTERIM_OVERRIDE_MAP"
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Organization_Interim_Record_Type_Prefix__c",
      "toolTip": "Defines what record type to use in Review Transaction in conjunction with Create Interim If No Organization setting.",
      "customFieldParams": {
        "label": "Organization Interim Record Type Prefix",
        "type": "text"
      }
    },
    {
      "fieldName": "BLANK_ORG_INTERIM_RECORD_TYPE_PREFIX"
    }
  ],
  [
    {
      "fieldName": "BLANK_FREQUENCY_INFO_SECTION",
      "customFieldParams": {
        "type": "header",
        "label": "Frequency Information"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Installment_Frequency_Map__c",
      "toolTip": "For overriding the standard frequency that is supported. Example format is {\"Annual\":12,\"Monthly\":1}",
      "jsonFieldParams": {
        "label": "Installment Frequency Map",
        "type": "object",
        "keyLabel": "Frequency",
        "valueLabel": "Number",
        "jsonKeysToValueList": [
          {
            "key": "[CUSTOM]",
            "valueCustomFieldParams": {
              "type": "number"
            }
          }
        ]
      }
    },
    {
      "fieldName": "BLANK_Installment_Frequency_Map"
    }
  ],
  [
    {
      "fieldName": "BLANK_FIELD_MAP_INFO_SECTION",
      "customFieldParams": {
        "type": "header",
        "label": "Field Map Information"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Session_Field_Map__c",
      "toolTip": "Map additional fields to be copied between the session and review transaction. Format is {\"Session Field API Name\":\"Review Transaction Field API Name\"}.",
      "jsonFieldParams": {
        "label": "Session Field Map",
        "type": "object",
        "keyLabel": "Session Field",
        "valueLabel": "Review Transaction Field",
        "jsonKeysToValueList": [
          {
            "key": "[CUSTOM]",
            "valueCustomFieldParams": {
              "type": "text"
            }
          }
        ]
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Designation_Detail_Field_Map__c",
      "toolTip": "Map additional fields to be copied between the designation detail and review transaction. Format is {\"Designation Detail Field API Name\":\"Review Transaction Field API Name\"}.",
      "jsonFieldParams": {
        "label": "Designation Detail Field Map",
        "type": "object",
        "keyLabel": "Designation Detail Field",
        "valueLabel": "Review Transaction Field",
        "jsonKeysToValueList": [
          {
            "key": "[CUSTOM]",
            "valueCustomFieldParams": {
              "type": "text"
            }
          }
        ]
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Pledge_Gift_Field_Map__c",
      "toolTip": "Map additional fields to be copied between the pledge/gift and review transaction. Format is {\"Pledge/Gift Field API Name\":\"Review Transaction Field API Name\"}.",
      "jsonFieldParams": {
